pub open spec fn utf16_well_formed(v: vstd::seq::Seq<u16>) -> bool {
    forall|i: int| 0 <= i < v.len() ==> {
        &&& ((0xD800u16 <= v[i] && v[i] <= 0xDBFFu16) ==> (i + 1 < v.len() && 0xDC00u16 <= v[i + 1] && v[i + 1] <= 0xDFFFu16))
        &&& ((0xDC00u16 <= v[i] && v[i] <= 0xDFFFu16) ==> (0 < i && 0xD800u16 <= v[i - 1] && v[i - 1] <= 0xDBFFu16))
    }
}

