pub open spec fn is_utf16_high_surrogate(unit: u16) -> bool {
    0xD800 <= unit && unit <= 0xDBFF
}

pub open spec fn is_utf16_low_surrogate(unit: u16) -> bool {
    0xDC00 <= unit && unit <= 0xDFFF
}

pub open spec fn is_utf16_lossy_decoding(input: Seq<u16>, output: Seq<char>) -> bool
    decreases input.len(),
{
    if input.len() == 0 {
        output == Seq::<char>::empty()
    } else if input.len() >= 2
        && is_utf16_high_surrogate(input[0])
        && is_utf16_low_surrogate(input[1])
    {
        output.len() > 0
            && output[0] as int
                == 0x10000
                    + (input[0] as int - 0xD800) * 0x400
                    + (input[1] as int - 0xDC00)
            && is_utf16_lossy_decoding(
                input.subrange(2, input.len() as int),
                output.subrange(1, output.len() as int),
            )
    } else {
        output.len() > 0
            && output[0] as int
                == if is_utf16_high_surrogate(input[0])
                    || is_utf16_low_surrogate(input[0])
                {
                    0xFFFD
                } else {
                    input[0] as int
                }
            && is_utf16_lossy_decoding(
                input.subrange(1, input.len() as int),
                output.subrange(1, output.len() as int),
            )
    }
}

