pub open spec fn spec_from_utf16be_lossy(bytes: Seq<u8>) -> Seq<char>
    decreases bytes.len(),
{
    if bytes.len() == 0 {
        seq![]
    } else if bytes.len() == 1 {
        seq!['\u{fffd}']
    } else {
        let first = bytes[0] as u32 * 256u32 + bytes[1] as u32;
        if 0xd800u32 <= first && first <= 0xdbffu32 && bytes.len() >= 4 {
            let second = bytes[2] as u32 * 256u32 + bytes[3] as u32;
            if 0xdc00u32 <= second && second <= 0xdfffu32 {
                let scalar = 0x10000u32
                    + (first - 0xd800u32) * 0x400u32
                    + (second - 0xdc00u32);
                seq![scalar as char]
                    + spec_from_utf16be_lossy(bytes.subrange(4, bytes.len() as int))
            } else {
                seq!['\u{fffd}']
                    + spec_from_utf16be_lossy(bytes.subrange(2, bytes.len() as int))
            }
        } else if 0xd800u32 <= first && first <= 0xdfffu32 {
            seq!['\u{fffd}']
                + spec_from_utf16be_lossy(bytes.subrange(2, bytes.len() as int))
        } else {
            seq![first as char]
                + spec_from_utf16be_lossy(bytes.subrange(2, bytes.len() as int))
        }
    }
}

