pub open spec fn iter_cmp_spec<A: core::cmp::Ord>(
    left: Seq<A>,
    right: Seq<A>,
) -> core::cmp::Ordering
    decreases left.len() + right.len()
{
    if left.len() == 0 {
        if right.len() == 0 {
            core::cmp::Ordering::Equal
        } else {
            core::cmp::Ordering::Less
        }
    } else if right.len() == 0 {
        core::cmp::Ordering::Greater
    } else {
        match left[0].cmp_spec(&right[0]) {
            core::cmp::Ordering::Equal => iter_cmp_spec(left.drop_first(), right.drop_first()),
            ordering => ordering,
        }
    }
}

